-- Fiche Le passé composé : avoir ou être ? (CM2) - conjugaison, notion 'passe_compose'. Relancer ce script remplace le contenu de la fiche.
insert into contenu_cours (classe, matiere, titre, contenu, statut, notion_id)
select 'cm2', 'conjugaison', 'Le passé composé : avoir ou être ?', $fiche$
[titre]Deux auxiliaires[/titre]
[cadre]Le passé composé = auxiliaire [b]avoir[/b] ou [b]être[/b] au présent + participe passé.
il [b]a[/b] vendu · tu [b]es[/b] resté[/cadre]
[page]
[titre]Les verbes avec être[/titre]
